-- ST250 separate persistent sandbox; only explicit sandbox bootstrap may install.
BEGIN;
SET LOCAL search_path=pg_catalog;
SELECT 1/(current_database()='subtrack_sandbox' AND SESSION_USER='subtrack_sandbox_bootstrap' AND current_setting('server_version_num')::int BETWEEN 160000 AND 169999)::int;
CREATE ROLE subtrack_sandbox_owner NOLOGIN NOSUPERUSER NOBYPASSRLS NOINHERIT NOCREATEDB NOCREATEROLE;
CREATE ROLE subtrack_sandbox_api_login LOGIN PASSWORD NULL NOSUPERUSER NOBYPASSRLS NOINHERIT NOCREATEDB NOCREATEROLE;
CREATE ROLE subtrack_sandbox_runtime NOLOGIN NOSUPERUSER NOBYPASSRLS NOINHERIT NOCREATEDB NOCREATEROLE;
CREATE ROLE subtrack_sandbox_auth_producer NOLOGIN NOSUPERUSER NOBYPASSRLS NOINHERIT NOCREATEDB NOCREATEROLE;
GRANT subtrack_sandbox_runtime,subtrack_sandbox_auth_producer TO subtrack_sandbox_api_login;
REVOKE ALL ON DATABASE subtrack_sandbox FROM PUBLIC;
GRANT CONNECT ON DATABASE subtrack_sandbox TO subtrack_sandbox_api_login;
REVOKE ALL ON SCHEMA public FROM PUBLIC;
GRANT USAGE ON SCHEMA public TO subtrack_sandbox_runtime,subtrack_sandbox_auth_producer,subtrack_sandbox_owner;
CREATE SCHEMA st250_auth AUTHORIZATION subtrack_sandbox_owner;
REVOKE ALL ON SCHEMA st250_auth FROM PUBLIC;
GRANT USAGE ON SCHEMA st250_auth TO subtrack_sandbox_runtime,subtrack_sandbox_auth_producer;
CREATE TYPE public.auth_method AS ENUM('MOCK');
CREATE TABLE public.identity(id uuid PRIMARY KEY,auth_method public.auth_method NOT NULL DEFAULT 'MOCK' CHECK(auth_method='MOCK'),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),deleted_at timestamptz CHECK(deleted_at IS NULL));
CREATE TABLE st250_auth.epoch(id text PRIMARY KEY CHECK(id='st250-sandbox-v1'),manifest_h text NOT NULL CHECK(manifest_h~'^[a-f0-9]{64}$'),watermark_ms bigint NOT NULL CHECK(watermark_ms>=0),active boolean NOT NULL);
CREATE TABLE st250_auth.migration(id integer PRIMARY KEY CHECK(id IN(1,2)),sha256 text NOT NULL CHECK(sha256~'^[a-f0-9]{64}$'));
CREATE TABLE st250_auth.capacity(id integer PRIMARY KEY CHECK(id=1));
CREATE TABLE st250_auth.capability(identity_id uuid PRIMARY KEY REFERENCES public.identity(id) ON DELETE RESTRICT,digest_h text NOT NULL UNIQUE CHECK(digest_h~'^[a-f0-9]{64}$'),created_ms bigint NOT NULL CHECK(created_ms>=0),expires_ms bigint NOT NULL CHECK(expires_ms=created_ms+2592000000),revoked_ms bigint CHECK(revoked_ms>=created_ms));
CREATE TABLE st250_auth.session(id uuid PRIMARY KEY,identity_id uuid NOT NULL REFERENCES st250_auth.capability(identity_id) ON DELETE RESTRICT,family_id uuid NOT NULL UNIQUE,refresh_h text NOT NULL UNIQUE CHECK(refresh_h~'^[a-f0-9]{64}$'),generation bigint NOT NULL DEFAULT 0 CHECK(generation>=0),created_ms bigint NOT NULL CHECK(created_ms>=0),expires_ms bigint NOT NULL CHECK(expires_ms>created_ms AND expires_ms<=created_ms+86400000),revoked_ms bigint CHECK(revoked_ms>=created_ms),UNIQUE(identity_id,id),CHECK(id<>family_id));
CREATE TABLE st250_auth.consumed_refresh(digest_h text PRIMARY KEY CHECK(digest_h~'^[a-f0-9]{64}$'),identity_id uuid NOT NULL,session_id uuid NOT NULL,FOREIGN KEY(identity_id,session_id) REFERENCES st250_auth.session(identity_id,id) ON DELETE RESTRICT);
CREATE TABLE st250_auth.reservation(key_h text PRIMARY KEY CHECK(key_h~'^[a-f0-9]{64}$'),request_h text NOT NULL CHECK(request_h~'^[a-f0-9]{64}$'),operation text NOT NULL CHECK(operation IN('bootstrap','resume','refresh')),transport text NOT NULL CHECK(transport='sandbox-mobile'),created_ms bigint NOT NULL CHECK(created_ms>=0));
INSERT INTO st250_auth.epoch VALUES('st250-sandbox-v1',current_setting('st250.manifest'),0,true);
INSERT INTO st250_auth.migration VALUES(1,current_setting('st250.foundation_sha256'));
INSERT INTO st250_auth.capacity VALUES(1);
ALTER TABLE public.identity OWNER TO subtrack_sandbox_owner;
ALTER TABLE st250_auth.epoch OWNER TO subtrack_sandbox_owner;
ALTER TABLE st250_auth.migration OWNER TO subtrack_sandbox_owner;
ALTER TABLE st250_auth.capacity OWNER TO subtrack_sandbox_owner;
ALTER TABLE st250_auth.capability OWNER TO subtrack_sandbox_owner;
ALTER TABLE st250_auth.session OWNER TO subtrack_sandbox_owner;
ALTER TABLE st250_auth.consumed_refresh OWNER TO subtrack_sandbox_owner;
ALTER TABLE st250_auth.reservation OWNER TO subtrack_sandbox_owner;
CREATE FUNCTION public.subtrack_principal_matches(owner_id uuid) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog AS $$ SELECT owner_id::text=coalesce(current_setting('app.user_id',true),'') AND owner_id::text=coalesce(current_setting('app.current_user_id',true),'') $$;
REVOKE ALL ON FUNCTION public.subtrack_principal_matches(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.subtrack_principal_matches(uuid) TO subtrack_sandbox_runtime,subtrack_sandbox_auth_producer,subtrack_sandbox_owner;
ALTER FUNCTION public.subtrack_principal_matches(uuid) OWNER TO subtrack_sandbox_owner;
ALTER TABLE public.identity ENABLE ROW LEVEL SECURITY;ALTER TABLE public.identity FORCE ROW LEVEL SECURITY;
CREATE POLICY identity_count_owner ON public.identity TO subtrack_sandbox_owner USING(true) WITH CHECK(true);
CREATE POLICY identity_producer ON public.identity TO subtrack_sandbox_auth_producer USING(true) WITH CHECK(true);
CREATE POLICY identity_runtime ON public.identity FOR SELECT TO subtrack_sandbox_runtime USING(public.subtrack_principal_matches(id));
ALTER TABLE st250_auth.epoch ENABLE ROW LEVEL SECURITY;ALTER TABLE st250_auth.epoch FORCE ROW LEVEL SECURITY;
ALTER TABLE st250_auth.migration ENABLE ROW LEVEL SECURITY;ALTER TABLE st250_auth.migration FORCE ROW LEVEL SECURITY;
ALTER TABLE st250_auth.capacity ENABLE ROW LEVEL SECURITY;ALTER TABLE st250_auth.capacity FORCE ROW LEVEL SECURITY;
ALTER TABLE st250_auth.capability ENABLE ROW LEVEL SECURITY;ALTER TABLE st250_auth.capability FORCE ROW LEVEL SECURITY;
ALTER TABLE st250_auth.session ENABLE ROW LEVEL SECURITY;ALTER TABLE st250_auth.session FORCE ROW LEVEL SECURITY;
ALTER TABLE st250_auth.consumed_refresh ENABLE ROW LEVEL SECURITY;ALTER TABLE st250_auth.consumed_refresh FORCE ROW LEVEL SECURITY;
ALTER TABLE st250_auth.reservation ENABLE ROW LEVEL SECURITY;ALTER TABLE st250_auth.reservation FORCE ROW LEVEL SECURITY;
CREATE POLICY epoch_read ON st250_auth.epoch FOR SELECT TO subtrack_sandbox_runtime,subtrack_sandbox_auth_producer USING(true);
CREATE POLICY epoch_fence ON st250_auth.epoch FOR UPDATE TO subtrack_sandbox_runtime,subtrack_sandbox_auth_producer USING(true) WITH CHECK(true);
CREATE POLICY migration_read ON st250_auth.migration FOR SELECT TO subtrack_sandbox_runtime,subtrack_sandbox_auth_producer USING(true);
CREATE POLICY capacity_lock ON st250_auth.capacity TO subtrack_sandbox_runtime,subtrack_sandbox_auth_producer,subtrack_sandbox_owner USING(true) WITH CHECK(true);
CREATE POLICY capability_count ON st250_auth.capability FOR SELECT TO subtrack_sandbox_owner USING(true);
CREATE POLICY capability_producer ON st250_auth.capability TO subtrack_sandbox_auth_producer USING(true) WITH CHECK(true);
CREATE POLICY capability_owner ON st250_auth.capability FOR SELECT TO subtrack_sandbox_runtime USING(public.subtrack_principal_matches(identity_id));
CREATE POLICY session_count ON st250_auth.session FOR SELECT TO subtrack_sandbox_owner USING(true);
CREATE POLICY session_producer ON st250_auth.session TO subtrack_sandbox_auth_producer USING(true) WITH CHECK(true);
CREATE POLICY session_owner ON st250_auth.session FOR SELECT TO subtrack_sandbox_runtime USING(public.subtrack_principal_matches(identity_id));
CREATE POLICY consumed_count ON st250_auth.consumed_refresh FOR SELECT TO subtrack_sandbox_owner USING(true);
CREATE POLICY consumed_producer ON st250_auth.consumed_refresh TO subtrack_sandbox_auth_producer USING(true) WITH CHECK(true);
CREATE POLICY reservation_count ON st250_auth.reservation FOR SELECT TO subtrack_sandbox_owner USING(true);
CREATE POLICY reservation_producer ON st250_auth.reservation TO subtrack_sandbox_auth_producer USING(true) WITH CHECK(true);
REVOKE ALL ON ALL TABLES IN SCHEMA st250_auth FROM PUBLIC;
REVOKE ALL ON public.identity FROM PUBLIC;
GRANT SELECT ON st250_auth.epoch,st250_auth.migration,st250_auth.capacity TO subtrack_sandbox_runtime,subtrack_sandbox_auth_producer;
GRANT UPDATE(watermark_ms) ON st250_auth.epoch TO subtrack_sandbox_runtime,subtrack_sandbox_auth_producer;
-- FOR UPDATE requires UPDATE privilege on at least one capacity column; there is no writable capacity count.
GRANT UPDATE(id) ON st250_auth.capacity TO subtrack_sandbox_runtime,subtrack_sandbox_auth_producer;
GRANT SELECT,INSERT ON public.identity,st250_auth.capability,st250_auth.session,st250_auth.consumed_refresh,st250_auth.reservation TO subtrack_sandbox_auth_producer;
GRANT UPDATE(revoked_ms) ON st250_auth.capability TO subtrack_sandbox_auth_producer;
GRANT UPDATE(refresh_h,generation,revoked_ms) ON st250_auth.session TO subtrack_sandbox_auth_producer;
GRANT SELECT ON public.identity,st250_auth.capability,st250_auth.session TO subtrack_sandbox_runtime;
CREATE FUNCTION st250_auth.lock_owner(owner_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE locked uuid;
BEGIN IF NOT public.subtrack_principal_matches(owner_id) THEN RAISE EXCEPTION 'Sandbox owner unavailable' USING ERRCODE='42501';END IF;
SELECT id INTO locked FROM public.identity WHERE id=owner_id AND deleted_at IS NULL FOR UPDATE;
IF locked IS NULL THEN RAISE EXCEPTION 'Sandbox owner unavailable' USING ERRCODE='42501';END IF;RETURN locked;END $$;
ALTER FUNCTION st250_auth.lock_owner(uuid) OWNER TO subtrack_sandbox_owner;
REVOKE ALL ON FUNCTION st250_auth.lock_owner(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION st250_auth.lock_owner(uuid) TO subtrack_sandbox_runtime,subtrack_sandbox_auth_producer;
COMMIT;
